EchoStation.Rendering.Editor.SceneSafetyGuard.RequireClean();var previous=UnityEngine.SceneManagement.SceneManager.GetActiveScene();var scene=UnityEditor.SceneManagement.EditorSceneManager.OpenScene(EchoStation.InfiltrationRefinement.Editor.RefinementScene.ScenePath,UnityEditor.SceneManagement.OpenSceneMode.Additive);
try{UnityEngine.Physics.SyncTransforms();return EchoStation.InfiltrationRefinement.Editor.RefinementScene.World(scene).GetComponentsInChildren<EchoStation.InfiltrationRefinement.RefinementDecoration>().Where(d=>d.Kind=="Mug"||d.Kind=="Computer").Select(d=>{bool ok=UnityEngine.Physics.Raycast(d.transform.position+UnityEngine.Vector3.up*.01f,UnityEngine.Vector3.down,out var hit,.1f);var art=ok?hit.collider.GetComponentInParent<EchoStation.InfiltrationArt.ArtSampleModel>():null;return new{name=d.name,position=d.transform.position.ToString(),hit=ok,collider=ok?hit.collider.name:null,role=art?art.Role:null,distance=ok?hit.distance:0};}).ToArray();}
finally{UnityEngine.SceneManagement.SceneManager.SetActiveScene(previous);UnityEditor.SceneManagement.EditorSceneManager.CloseScene(scene,true);}
